// Extrae los datos devueltos por FastAPI y prepara la gráfica binaria para el email
const item = $input.first().json;
const params = $('Configuración Parámetros').first().json;

const ticker = item.ticker;
const current = item.current;
const max = item.max;
const min = item.min;
const mean = item.mean;
const period = item.period;
const recipient = params.recipient;

// Construye el HTML enriquecido del correo
const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f4f7f6; margin: 0; padding: 20px; }
    .container { max-width: 600px; margin: auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.06); }
    .header { background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%); color: #ffffff; padding: 25px 20px; text-align: center; }
    .header h1 { margin: 0; font-size: 22px; }
    .content { padding: 25px; }
    .stats-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin: 20px 0; }
    .stat-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px 15px; }
    .stat-title { font-size: 12px; color: #64748b; text-transform: uppercase; margin-bottom: 5px; }
    .stat-value { font-size: 18px; font-weight: bold; color: #0f172a; }
    .stat-value.current { color: #16a34a; }
    .chart-container { margin-top: 25px; text-align: center; }
    .chart-container img { max-width: 100%; border-radius: 8px; border: 1px solid #e2e8f0; }
    .footer { text-align: center; padding: 15px; font-size: 12px; color: #94a3b8; border-top: 1px solid #f1f5f9; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Reporte Financiero Automatizado</h1>
      <p style="margin: 5px 0 0 0; opacity: 0.9;">Acción: <strong>${ticker}</strong> | Últimos <strong>${period}</strong></p>
    </div>
    <div class="content">
      <div class="stats-grid">
        <div class="stat-card">
          <div class="stat-title">Precio Actual</div>
          <div class="stat-value current">$${current}</div>
        </div>
        <div class="stat-card">
          <div class="stat-title">Precio Promedio</div>
          <div class="stat-value">$${mean}</div>
        </div>
        <div class="stat-card">
          <div class="stat-title">Máximo Periodo</div>
          <div class="stat-value">$${max}</div>
        </div>
        <div class="stat-card">
          <div class="stat-title">Mínimo Periodo</div>
          <div class="stat-value">$${min}</div>
        </div>
      </div>
      <div class="chart-container">
        <h3 style="color: #334155; margin-bottom: 10px;">Evolución de Precios de Cierre</h3>
        <img src="data:image/png;base64,${item.close_chart_base64}" alt="Gráfica ${ticker}" />
      </div>
    </div>
    <div class="footer">
      Generado por FastAPI & n8n • Asistente Financiero
    </div>
  </div>
</body>
</html>
`;

return [
  {
    json: {
      ticker,
      period,
      recipient,
      subject: `📈 Reporte Bursátil: ${ticker} ($${current} USD)`,
      emailHtml
    }
  }
];
